// og-fallback — the branded 1200x630 share card served on the /api/og worst-case path.
//
// WHY A SEPARATE MODULE (quick-260807-vl1): og-cover.ts owns the resolve chain; the fallback asset
// is a different concern and the bytes constant below is large enough to bury it. `+server.ts` may
// export ONLY HTTP verbs, so it cannot live there either.
//
// WHY A RASTER, NOT THE SVG IT REPLACES: no major platform renders an SVG `og:image` — WhatsApp,
// iMessage, Twitter, Slack and Facebook all skip it (30-RESEARCH.md §C.11 / §D.15, and the user's
// own WhatsApp card came through blank). The previous constant here was an inlined `static/og.svg`,
// so every all-tiers-miss card was invisible in exactly the messengers this endpoint exists for.
//
// ZERO-NETWORK / ZERO-SUBREQUEST IS LOCKED (§C.11 + §D.15). Inlining beats every alternative on the
// worst-case path: zero network, zero subrequest, zero loop risk. Do NOT `fetch()` /og.jpg from the
// static assets, and do NOT 302 to it — WhatsApp's crawler does not reliably follow a redirect on
// an image URL. The bytes are decoded ONCE at module scope (per isolate), not per request.
//
// THE ASSET: `static/og.jpg`, 1200x630, 48,744 bytes, rasterized from `static/og.svg` (which is
// KEPT as the source artwork) with `sips -s format jpeg -s formatOptions 80`. JPEG rather than PNG
// because the card is a full-bleed gradient: the PNG-24 raster was 735,780 bytes (a ~980 KB base64
// literal), the q80 JPEG is 48,744. If static/og.svg is ever re-themed, RE-RASTERIZE and regenerate
// the base64 constant below — nothing checks that they agree.

/** The card's real content type. A raster, never `image/svg+xml`. */
export const OG_FALLBACK_TYPE = 'image/jpeg';

/**
 * `atob` + charCode loop: `atob` exists in workerd AND Node >= 22, so this needs no `Buffer`
 * (absent at the edge) and no `fetch`. Runs exactly once, at module eval.
 *
 * The `Uint8Array<ArrayBuffer>` return is load-bearing, not decoration: `BodyInit`'s BufferSource
 * arm is `ArrayBufferView<ArrayBuffer>`, and a bare `Uint8Array` infers as
 * `Uint8Array<ArrayBufferLike>` (which admits SharedArrayBuffer) — so `new Response(bytes)` fails
 * to typecheck. Pinning the buffer type is what keeps the route cast-free.
 */
function decodeBase64(b64: string): Uint8Array<ArrayBuffer> {
	const bin = atob(b64);
	const bytes = new Uint8Array(bin.length);
	for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
	return bytes;
}

